CREATE TABLE IF NOT EXISTS tb_logradouro (id_logradouro INT AUTO_INCREMENT PRIMARY KEY, cep VARCHAR(8) NOT NULL UNIQUE, nome VARCHAR(150) NOT NULL, bairro VARCHAR(100) NOT NULL, cidade VARCHAR(100) NOT NULL, estado CHAR(2) NOT NULL, pais VARCHAR(50) NOT NULL DEFAULT 'Brasil') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tb_aluno (id_aluno INT AUTO_INCREMENT PRIMARY KEY, cpf VARCHAR(11) NOT NULL UNIQUE, nome VARCHAR(150) NOT NULL, nascimento DATE NOT NULL, telefone VARCHAR(15) NOT NULL, email VARCHAR(150) NOT NULL, logradouro_id INT NOT NULL, numero VARCHAR(20) NOT NULL, complemento VARCHAR(100), senha VARCHAR(255) NOT NULL, foto LONGBLOB, FOREIGN KEY (logradouro_id) REFERENCES tb_logradouro(id_logradouro)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tb_colaborador (id_colaborador INT AUTO_INCREMENT PRIMARY KEY, cpf VARCHAR(11) NOT NULL UNIQUE, nome VARCHAR(150) NOT NULL, nascimento DATE NOT NULL, telefone VARCHAR(15) NOT NULL, email VARCHAR(150) NOT NULL, logradouro_id INT NOT NULL, numero VARCHAR(20) NOT NULL, complemento VARCHAR(100), senha VARCHAR(255) NOT NULL, foto LONGBLOB, admissao DATE NOT NULL, tipo INT NOT NULL, vinculo INT NOT NULL, salario DECIMAL(10,2) NOT NULL DEFAULT 0, FOREIGN KEY (logradouro_id) REFERENCES tb_logradouro(id_logradouro)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tb_matricula (id_matricula INT AUTO_INCREMENT PRIMARY KEY, aluno_id INT NOT NULL, plano INT NOT NULL, data_inicio DATE NOT NULL, data_fim DATE NOT NULL, objetivo VARCHAR(500) NOT NULL, restricao_medica INT NOT NULL DEFAULT 0, obs_restricao VARCHAR(500), laudo_medico LONGBLOB, FOREIGN KEY (aluno_id) REFERENCES tb_aluno(id_aluno)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tb_acesso (id_acesso INT AUTO_INCREMENT PRIMARY KEY, pessoa_tipo INT NOT NULL, pessoa_id INT NOT NULL, data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;